mapper.select:
SELECT * FROM ai_human_handoffs
WHERE status = #{status}
ORDER BY created_at DESC

mapper.update:
UPDATE ai_human_handoffs
SET status = 'in_progress', assigned_agent = #{agent}, updated_at = #{now}
WHERE id = #{id} AND status = 'pending'

UPDATE ai_human_handoffs
SET status = 'closed', assigned_agent = #{agent}, note = #{note}, resolved_at = #{now}, updated_at = #{now}
WHERE id = #{id} AND status = 'in_progress'

UPDATE ai_human_handoffs
SET assigned_agent = #{targetAgent}, note = #{note}, updated_at = #{now}
WHERE id = #{id} AND status = 'in_progress'
